import{_ as l,l as r,o as e,c as n,v as t,p as s,x as o,d,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"视频生成的时空建模","description":"","frontmatter":{"title":"视频生成的时空建模","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/video-gen-spatiotemporal.md","filePath":"llm/video-gen-spatiotemporal.md","lastUpdated":1789023840000}'),h={name:"llm/video-gen-spatiotemporal.md"};function f(c,a,_,E,u,A){const i=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="视频生成的时空建模" tabindex="-1">视频生成的时空建模 <a class="header-anchor" href="#视频生成的时空建模" aria-label="Permalink to &quot;视频生成的时空建模&quot;">​</a></h1><div class="epigraph"><p>多一维时间之后，失败从「这一帧糊」变成「下一帧物体跳、光变、身份换」。生成器必须在时空上共享计算，而不是独立画每帧。</p><footer>—— Ho 等 Video Diffusion Models；Blattmann 等 Align your Latents / Stable Video Diffusion</footer></div><p><a href="/llm/diffusion-distillation">上一课</a>把单图采样步数压下去。理解侧<a href="/llm/video-tokens">视频 token</a> 写的是抽帧阅读。本课缺口是生成：潜空间或像素上的时空 U-Net / Transformer，让运动连续。本单元生成基础到此；下一课改听与说。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对每帧独立做 <a href="/llm/ddpm">DDPM</a> 或文生图，时间上无耦合，闪烁是默认。Video diffusion 把噪声过程定义在 \\(x\\in\\mathbb{R}^{F\\times H\\times W\\times C}\\)（或潜空间），网络用时空卷积或时空注意力。Align your Latents 在图像 LDM 上加时间层，用视频数据微调。SVD 把这条路做到可发布的图生视频。</p><p>文本只有全局句时，时间对齐弱（后课音画同步再钉）。分辨率 × 帧数 × 步数是立方账，少步与潜空间是前提，不是锦上添花。</p><p><span class="marginnote">因果时间注意力可流式出帧；双向时间更稳但必须见未来，不能边看边生成。产品要先选交互还是离线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>骨干：在 <a href="/llm/latent-vae">VAE</a> 潜格上加时间维；条件：文本、首帧、光流或姿态。训练用短 clip，推理用重叠或滑动延时，否则长视频会漂。评测：FVD、闪烁、身份保持、运动与提示遵守，不要只用单帧 FID。</p>',9)),(e(),s(m,null,{default:o(()=>[p(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E6%97%B6%E7%A9%BA%E6%BD%9C%E5%8F%98%E9%87%8F%22%5D%20--%3E%20ST%5B%22%E6%97%B6%E7%A9%BA%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%88%96%E5%8D%B7%E7%A7%AF%22%5D%0A%20%20ST%20--%3E%20DEN%5B%22%E8%81%94%E5%90%88%E5%8E%BB%E5%99%AA%22%5D%0A%20%20DEN%20--%3E%20FR%5B%22%E8%BF%9E%E8%B4%AF%E5%B8%A7%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>时间层让同一空间位置在相邻帧共享键值，物体才能「移动而不是重生」。若时间感受野短，只有局部光流稳、长程动作仍跳。这与理解侧记忆对称：生成器没有外挂记忆时，长程一致性必须写进层与条件（首帧、草图）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理口型与音轨对齐。下一单元从语音 codec 语言建模开始。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>视频生成要时空联合去噪，禁止独立逐帧。</li><li>算力是帧 × 空间 × 步数；潜空间与少步是前提。</li><li>长 clip 会漂，要条件与延时策略。</li><li>出处：Ho 等 Video Diffusion Models；Blattmann 等 SVD / Align your Latents。</li></ul>',6))])}const T=l(h,[["render",f]]);export{D as __pageData,T as default};
